  background: #e8ebe3;
  font-synthesis: none;
  --basalt: #18211f;
  --paper: #f2f3ed;
  --paper-deep: #e7e9e1;
  --ink: #1c2825;
  --slate: #65706a;
  --line: #c9cec4;
  --mineral: #c58a3e;
  --ocean: #3f6f76;
