kbd { border: 1px solid var(--line); background: var(--paper); padding: 1px 6px; color: var(--slate); }
.filter-button, .reset-button, .error-state button, .empty-state button { height: 44px; display: flex; align-items: center; gap: 8px; padding: 0 14px; border: 1px solid #aeb6aa; background: #f7f8f3; font-weight: 680; }
.filter-button.has-filters { border-color: var(--ocean); }
