.reset-button { border: 0; background: transparent; color: #6c5042; }
.sort-control { margin-left: auto; display: flex; align-items: center; gap: 8px; color: var(--slate); font-size: 13px; }
.sort-control select, .filter-panel select { min-height: 42px; border: 1px solid #b8bfb4; background: white; padding: 0 34px 0 11px; }
.filter-panel { padding: 16px 32px 20px; display: grid; grid-template-columns: 1.25fr 1.25fr repeat(4, 1fr); gap: 16px; background: #dde1d8; border-bottom: 1px solid #bdc4b9; box-shadow: inset 0 5px 12px rgba(27,39,35,.05); }
.filter-panel label { min-width: 0; font-size: 12px; font-weight: 720; color: #4b5853; }
.filter-panel output { float: right; color: var(--ink); }
.filter-panel input[type="range"] { width: 100%; margin: 12px 0 0; accent-color: var(--ocean); }
.filter-panel select { display: block; width: 100%; margin-top: 6px; }
.check-control { display: flex; align-items: end; padding-bottom: 2px; }
.check-control input { width: 20px; height: 20px; margin: 0 8px 11px 0; accent-color: var(--ocean); }
.check-control span { min-height: 42px; flex: 1; display: flex; align-items: center; gap: 7px; border: 1px solid #b8bfb4; background: white; padding: 0 10px; }
.mobile-view-tabs { display: none; }

.workspace { display: grid; grid-template-columns: minmax(0, 1.65fr) minmax(345px, .72fr); height: min(630px, calc(100vh - 310px)); min-height: 470px; border-bottom: 1px solid var(--line); position: relative; }
.map-panel { position: relative; min-width: 0; overflow: hidden; border-right: 1px solid var(--line); }
.map-wrap, .map-canvas { width: 100%; height: 100%; background: #dfe4de; }
.leaflet-container { font-family: inherit; }
.leaflet-control-attribution { font-size: 9px !important; background: rgba(244,245,240,.78) !important; }
.leaflet-tooltip { border: 1px solid var(--basalt); border-radius: 0; box-shadow: 4px 4px 0 rgba(24,33,31,.15); padding: 8px 10px; font-size: 12px; }
.quake-marker { stroke: #f3f4ee; }
.marker-minor { fill: var(--minor); }
.marker-moderate { fill: var(--moderate); }
.marker-strong { fill: var(--strong); }
.marker-major { fill: var(--major); }
.marker-unknown { fill: #777; stroke-dasharray: 2 2; }
.quake-marker.is-active { stroke: var(--basalt); filter: drop-shadow(0 0 3px white); }
.map-legend { position: absolute; left: 16px; bottom: 22px; z-index: 500; max-width: 250px; display: flex; flex-wrap: wrap; gap: 7px 12px; background: rgba(246,247,241,.93); border: 1px solid #aeb7ac; padding: 10px 12px; font-size: 11px; box-shadow: 3px 3px 0 rgba(36,49,44,.1); }
.map-legend span { display: flex; align-items: center; gap: 5px; }
.map-legend small { flex-basis: 100%; color: var(--slate); }
.legend-dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; border: 1px solid white; box-shadow: 0 0 0 1px #53625c; }
.legend-dot.minor { background: var(--minor); } .legend-dot.moderate { background: var(--moderate); } .legend-dot.strong { background: var(--strong); } .legend-dot.major { background: var(--major); }
.map-count { position: absolute; right: 14px; top: 14px; z-index: 500; display: flex; align-items: center; gap: 6px; background: var(--basalt); color: white; padding: 7px 10px; font-size: 11px; text-transform: uppercase; letter-spacing: .07em; }
.data-banner { position: absolute; z-index: 600; top: 10px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 7px; background: #fff3db; border: 1px solid #c99041; padding: 8px 12px; font-size: 12px; box-shadow: 2px 2px 0 rgba(60,45,23,.12); }
.data-banner button { border: 0; background: transparent; text-decoration: underline; font-weight: 700; }

.stream-panel { min-width: 0; display: flex; flex-direction: column; background: var(--paper); }
.stream-head { min-height: 67px; padding: 13px 17px 10px; border-bottom: 1px solid var(--line); display: flex; align-items: center; justify-content: space-between; }
.stream-head h2 { margin: 0; font-family: 'Geologica Variable'; font-size: 18px; font-weight: 560; }
.stream-head .section-kicker { margin-bottom: 2px; }
.stream-head > svg { color: var(--slate); }
.stream-body { min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.event-row { width: 100%; min-height: 86px; display: grid; grid-template-columns: 60px minmax(0, 1fr) auto; gap: 11px; align-items: center; border: 0; border-bottom: 1px solid #d5d9d0; background: transparent; text-align: left; padding: 10px 14px 10px 12px; position: relative; }
.event-row:hover, .event-row.hovered { background: #e8ebe3; }
.event-row.selected { background: #dce4df; box-shadow: inset 4px 0 var(--ocean); }
.event-row.selected::after { content: 'SELECTED'; position: absolute; right: 11px; top: 7px; font-size: 8px; font-weight: 800; letter-spacing: .13em; color: var(--ocean); }
.mag { width: 54px; height: 54px; display: grid; place-items: center; border-radius: 50%; color: white; font-family: 'Geologica Variable'; font-weight: 680; font-size: 14px; border: 3px double rgba(255,255,255,.76); }
.medallion-minor { background: var(--minor); } .medallion-moderate { background: var(--moderate); } .medallion-strong { background: var(--strong); } .medallion-major { background: var(--major); } .medallion-unknown { background: #777; }
.event-copy { min-width: 0; }
.event-copy strong { display: block; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-size: 14px; }
.event-copy > span { margin-top: 6px; display: flex; align-items: center; gap: 5px; color: var(--slate); font-size: 11px; }
.event-signals { max-width: 82px; display: flex; justify-content: end; align-items: end; flex-direction: column; gap: 4px; color: #728079; }
.signal { display: flex; align-items: center; gap: 3px; font-size: 9px; font-weight: 780; text-transform: uppercase; }
.tsunami { color: #315f6a; }
.alert-green { color: #3e7454; } .alert-yellow { color: #765b12; } .alert-orange { color: #a34c20; } .alert-red { color: #9e2e28; }

.detail-panel { position: absolute; z-index: 700; right: 0; top: 0; width: min(430px, 42vw); height: 100%; overflow-y: auto; background: #f5f5ef; border-left: 1px solid var(--basalt); box-shadow: -12px 0 35px rgba(30,39,36,.2); padding: 22px; animation: slide-in .22s ease-out; }
.detail-top { display: flex; justify-content: space-between; align-items: start; }
.detail-panel .icon-button { border-color: var(--line); }
.detail-magnitude { font-family: 'Geologica Variable'; font-size: 57px; font-weight: 730; line-height: 1; letter-spacing: -.07em; color: var(--rust); }
.assessment { display: inline-flex; align-items: center; gap: 7px; margin: 13px 0 18px; padding: 7px 9px; border: 1px solid currentColor; font-size: 11px; font-weight: 760; text-transform: uppercase; letter-spacing: .05em; }
.assessment-minor, .assessment-moderate { color: var(--ocean); } .assessment-strong { color: #9a571f; } .assessment-major { color: var(--rust); }
.detail-panel h2 { margin-bottom: 8px; font-family: 'Geologica Variable'; font-size: 25px; font-weight: 550; line-height: 1.16; letter-spacing: -.025em; }
.detail-time { color: var(--ink); display: grid; grid-template-columns: 18px 1fr; column-gap: 7px; align-items: center; font-weight: 670; }
.detail-time span { grid-column: 2; color: var(--slate); font-size: 12px; font-weight: 450; }
.detail-grid { display: grid; grid-template-columns: 1fr 1fr; border-top: 1px solid var(--line); border-left: 1px solid var(--line); margin: 21px 0; }
.detail-grid > div { min-height: 105px; padding: 12px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.detail-grid span { display: flex; align-items: center; gap: 4px; color: var(--slate); font-size: 11px; text-transform: uppercase; letter-spacing: .07em; }
.detail-grid strong { display: block; font-family: 'Geologica Variable'; font-size: 19px; margin: 8px 0 4px; }
.detail-grid small { color: var(--slate); line-height: 1.2; }
.coordinates { display: flex; gap: 7px; align-items: center; font-family: 'Geologica Variable'; padding: 10px 0; border-bottom: 1px solid var(--line); }
.detail-flags { display: flex; flex-wrap: wrap; gap: 8px; padding: 13px 0; }
.detail-flags span { display: flex; gap: 5px; align-items: center; border: 1px solid var(--line); padding: 5px 8px; font-size: 11px; text-transform: capitalize; }
.magnitude-note { background: #e4e7df; border-left: 3px solid var(--mineral); padding: 11px 13px; margin: 9px 0 16px; }
.magnitude-note p, .authority-note { margin: 4px 0 0; color: var(--slate); font-size: 12px; line-height: 1.4; }
.usgs-link { min-height: 46px; display: flex; justify-content: center; align-items: center; gap: 8px; background: var(--basalt); color: white; text-decoration: none; font-weight: 700; }
.authority-note { margin-top: 12px; }

.timeline { background: var(--basalt); color: #edf0e9; padding: 16px 31px 19px; border-bottom: 1px solid #3b4641; }
.timeline-heading { display: flex; justify-content: space-between; align-items: end; }
.timeline-heading .section-kicker { color: #91a098; }
.timeline-heading h2 { margin: 0; font-family: 'Geologica Variable'; font-size: 17px; font-weight: 480; }
.timeline-heading p { margin: 0; color: #aeb8b2; font-size: 12px; max-width: 40%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.trace { position: relative; height: 90px; margin: 5px 0 0; }
.trace svg { display: block; width: 100%; height: 79px; overflow: visible; }
.trace-baseline { stroke: #53625c; stroke-width: .25; vector-effect: non-scaling-stroke; }
.trace-line { fill: none; stroke: #889890; stroke-width: .42; vector-effect: non-scaling-stroke; opacity: .65; }
.trace-point { fill: #d4a25c; stroke: var(--basalt); stroke-width: .28; vector-effect: non-scaling-stroke; }
.trace-point.selected { fill: #f7e7c8; stroke: #d16b42; stroke-width: .8; }
.timeline-start, .timeline-end { position: absolute; bottom: 0; color: #7f8d86; font-size: 10px; text-transform: uppercase; letter-spacing: .1em; }
.timeline-start { left: 0; } .timeline-end { right: 0; }
.scrubber-label { display: block; position: relative; height: 16px; margin-top: -33px; margin-bottom: 17px; }
.scrubber { appearance: none; width: 100%; height: 16px; opacity: .01; cursor: ew-resize; }
.scrubber:focus-visible { opacity: .3; outline-color: #e7be7d; }
.timeline-accessible { margin: 4px 0 0; color: #91a098; font-size: 11px; }

.loading-shell { height: 520px; display: grid; grid-template-columns: 2fr 1fr; gap: 1px; background: var(--line); }
.skeleton { background: linear-gradient(100deg, #dde1d8 30%, #eef0e9 50%, #dde1d8 70%); background-size: 200% 100%; animation: shimmer 1.5s infinite; }
.skeleton-lines { padding: 20px; background: var(--paper); }
.skeleton-lines .skeleton { height: 64px; margin-bottom: 10px; }
.error-state, .empty-state { min-height: 320px; display: grid; place-items: center; align-content: center; text-align: center; padding: 30px; }
.error-state > svg, .empty-state > svg { width: 36px; height: 36px; color: var(--rust); margin-bottom: 12px; }
.error-state h2, .empty-state h3 { margin-bottom: 7px; font-family: 'Geologica Variable'; }
.error-state p, .empty-state p { max-width: 460px; color: var(--slate); }
.error-state button, .empty-state button { margin: auto; }

footer { min-height: 62px; padding: 13px 31px; background: var(--basalt); color: #9eaaa4; display: flex; justify-content: space-between; align-items: center; gap: 20px; font-size: 11px; }
footer div { display: flex; align-items: center; gap: 6px; }
footer a { color: #dce1dd; }

@keyframes spin { to { transform: rotate(360deg); } }
@keyframes shimmer { to { background-position: -200% 0; } }
@keyframes slide-in { from { transform: translateX(40px); opacity: .2; } }

@media (max-width: 1050px) {
  .topbar { grid-template-columns: 230px 1fr auto; padding: 0 18px; }
  .live-status span { display: none; }
  .overview-summary div { min-width: 105px; padding-inline: 12px; }
  .filter-panel { grid-template-columns: repeat(3, 1fr); }
  .workspace { grid-template-columns: 1.45fr minmax(330px, .8fr); }
  .timeline { padding-inline: 20px; }
}

@media (max-width: 760px) {
  .topbar { height: auto; min-height: 64px; padding: 9px 12px; grid-template-columns: 1fr auto; }
  .brand small { display: none; }
  .range-tabs { grid-row: 2; grid-column: 1 / -1; width: 100%; margin-top: 9px; }
  .range-tabs button { flex: 1; padding-inline: 6px; min-height: 40px; }
  .top-actions .live-status, .top-actions button:last-child { display: none; }
  .overview-head { min-height: 0; display: block; padding: 20px 16px 15px; }
  .headline h1 { font-size: 27px; }
  .headline p { font-size: 13px; }
  .overview-summary { margin-top: 18px; width: 100%; }
  .overview-summary div { flex: 1; min-width: 0; padding: 11px 8px; }
  .overview-summary strong { font-size: 18px; }
  .overview-summary span { font-size: 9px; }
  .control-deck { padding: 9px 12px; flex-wrap: wrap; }
  .search-box { width: calc(100% - 112px); flex: 1; }
  kbd, .sort-control > span { display: none; }
  .sort-control { margin-left: 0; flex: 1; }
  .sort-control select { width: 100%; }
  .reset-button { padding-inline: 8px; }
  .filter-panel { padding: 14px 12px; grid-template-columns: 1fr 1fr; gap: 13px 10px; max-height: 52vh; overflow-y: auto; }
  .filter-panel .check-control { grid-column: 1 / -1; }
  .mobile-view-tabs { display: grid; grid-template-columns: 1fr 1fr; padding: 8px 12px; gap: 8px; background: #d8dcd3; border-bottom: 1px solid var(--line); }
  .mobile-view-tabs button { min-height: 44px; border: 1px solid #adb5aa; background: #eceee7; display: flex; align-items: center; justify-content: center; gap: 7px; font-weight: 700; }
  .mobile-view-tabs button.active { background: var(--basalt); color: white; border-color: var(--basalt); }
  .workspace { height: 58vh; min-height: 480px; display: block; }
  .workspace.mobile-map .stream-panel, .workspace.mobile-list .map-panel { display: none; }
  .map-panel, .stream-panel { width: 100%; height: 100%; border: 0; }
  .map-legend { left: 9px; bottom: 17px; max-width: 224px; padding: 8px; gap: 5px 9px; }
  .data-banner { width: calc(100% - 20px); justify-content: center; }
  .event-row { min-height: 82px; grid-template-columns: 55px minmax(0, 1fr) auto; padding-inline: 10px; }
  .mag { width: 50px; height: 50px; }
  .event-copy strong { white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  .detail-panel { position: fixed; width: 100%; height: min(78vh, 680px); top: auto; bottom: 0; border: 0; border-top: 2px solid var(--basalt); box-shadow: 0 -18px 45px rgba(20,29,26,.28); padding: 18px 16px 28px; animation: sheet-in .24s ease-out; }
  .detail-magnitude { font-size: 46px; }
  .detail-panel h2 { font-size: 22px; }
  .timeline { padding: 15px 13px; }
  .timeline-heading p { display: none; }
  .trace { height: 78px; }
  .timeline-accessible { line-height: 1.35; }
  footer { display: block; padding: 17px 15px; }
  footer div + div { margin-top: 9px; }
  .loading-shell { height: 500px; grid-template-columns: 1fr; }
  .skeleton-lines { display: none; }
}

@keyframes sheet-in { from { transform: translateY(50px); opacity: .3; } }

@media (max-width: 410px) {
  .brand strong { font-size: 18px; }
  .topbar .icon-button { width: 42px; height: 42px; }
  .headline h1 { font-size: 24px; }
  .overview-summary div:last-child { display: none; }
  .filter-panel { grid-template-columns: 1fr; }
  .filter-panel .check-control { grid-column: auto; }
  .filter-button { padding-inline: 11px; }
  .sort-control { min-width: 180px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

@media (forced-colors: active) {
  .quake-marker, .legend-dot, .mag { forced-color-adjust: none; border: 2px solid CanvasText; }
  .event-row.selected { outline: 3px solid Highlight; }
}

tool_use_result.content:
:root {
  font-family: 'Source Sans 3 Variable', system-ui, sans-serif;
  color: #1c2825;
  background: #e8ebe3;
  font-synthesis: none;
  --basalt: #18211f;
  --paper: #f2f3ed;
  --paper-deep: #e7e9e1;
  --ink: #1c2825;
  --slate: #65706a;
  --line: #c9cec4;
  --mineral: #c58a3e;
  --ocean: #3f6f76;
  --rust: #a74435;
  --focus: #176e99;
  --major: #a74435;
  --strong: #c56f37;
  --moderate: #367682;
  --minor: #65746b;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; min-width: 320px; min-height: 100vh; background: var(--paper-deep); }
button, input, select { font: inherit; }
button, select, input { color: inherit; }
button { cursor: pointer; }
a { color: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
button:disabled { cursor: wait; opacity: .65; }
.sr-only { position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.skip-link { position: fixed; left: 12px; top: -80px; z-index: 9999; background: white; padding: 12px 16px; font-weight: 700; }
.skip-link:focus { top: 12px; }

.app-shell { min-height: 100vh; background: radial-gradient(circle at 50% 15%, rgba(255,255,255,.45), transparent 34%), var(--paper-deep); }
.topbar { height: 72px; padding: 0 26px; background: var(--basalt); color: #f2f3ed; display: grid; grid-template-columns: 270px 1fr 270px; align-items: center; border-bottom: 1px solid #35413d; position: sticky; top: 0; z-index: 1000; }
.brand { display: flex; align-items: center; gap: 12px; }
.brand strong { font-family: 'Geologica Variable', sans-serif; font-size: 20px; letter-spacing: -.04em; }
.brand small { display: block; color: #9da8a2; font-size: 11px; text-transform: uppercase; letter-spacing: .13em; margin-top: 2px; }
.brand-mark { width: 34px; height: 34px; display: grid; place-content: center; gap: 3px; border: 1px solid #4d5c56; transform: rotate(-4deg); }
.brand-mark span { display: block; width: 21px; height: 2px; background: #d1a35d; transform-origin: center; }
.brand-mark span:first-child { transform: rotate(11deg); }
.brand-mark span:nth-child(2) { width: 25px; transform: rotate(-7deg); }
.brand-mark span:last-child { transform: rotate(5deg); }
.range-tabs { justify-self: center; display: flex; padding: 4px; gap: 2px; border: 1px solid #394641; background: #111917; }
.range-tabs button { min-height: 38px; border: 0; padding: 0 17px; background: transparent; color: #adb6b1; font-weight: 650; font-size: 13px; }
.range-tabs button:hover { color: white; background: #222d29; }
.range-tabs button.active { color: #19211f; background: #e8e9e2; box-shadow: inset 0 -2px #c58a3e; }
.top-actions { justify-self: end; display: flex; gap: 8px; align-items: center; }
.icon-button { width: 44px; height: 44px; padding: 0; display: grid; place-items: center; border: 1px solid currentColor; background: transparent; color: inherit; }
.icon-button svg { width: 18px; }
.topbar .icon-button { border-color: #3d4a45; color: #cad0cc; }
.topbar .icon-button:hover { background: #29342f; color: white; }
.live-status { display: flex; gap: 7px; align-items: center; margin-right: 4px; color: #bdc6c1; font-size: 12px; }
.live-status i { width: 8px; height: 8px; border-radius: 50%; background: #63a87c; box-shadow: 0 0 0 4px rgba(99,168,124,.14); }
.live-status.stale i { background: #d19850; box-shadow: 0 0 0 4px rgba(209,152,80,.15); }
.spin { animation: spin .8s linear infinite; }

main { width: min(1800px, 100%); margin: auto; }
.overview-head { min-height: 154px; padding: 26px 32px 22px; display: flex; align-items: end; justify-content: space-between; gap: 30px; border-bottom: 1px solid var(--line); position: relative; overflow: hidden; }
.overview-head::before { content: ''; position: absolute; inset: 0; pointer-events: none; opacity: .28; background: repeating-radial-gradient(ellipse at 73% 150%, transparent 0 37px, #aeb7ac 38px 39px); }
.headline, .overview-summary { position: relative; z-index: 1; }
.section-kicker { display: block; margin-bottom: 6px; font-size: 11px; font-weight: 760; color: #65706a; letter-spacing: .13em; text-transform: uppercase; }
h1, h2, h3, p { margin-top: 0; }
.headline h1 { margin-bottom: 4px; max-width: 950px; font-family: 'Geologica Variable', sans-serif; font-size: clamp(25px, 3vw, 44px); font-weight: 480; line-height: 1.08; letter-spacing: -.045em; }
.headline h1 em { color: var(--rust); font-style: normal; font-weight: 760; }
.headline p { margin-bottom: 0; color: var(--slate); }
.overview-summary { display: flex; align-items: stretch; background: rgba(244,245,240,.75); border: 1px solid var(--line); backdrop-filter: blur(4px); }
.overview-summary div { min-width: 124px; padding: 15px 17px 13px; border-right: 1px solid var(--line); }
.overview-summary div:last-child { border: 0; }
.overview-summary strong { display: block; font-family: 'Geologica Variable'; font-size: 22px; line-height: 1; }
.overview-summary span { display: block; color: var(--slate); font-size: 11px; margin-top: 7px; }

.control-deck { min-height: 64px; padding: 10px 20px 10px 32px; display: flex; gap: 10px; align-items: center; border-bottom: 1px solid var(--line); background: rgba(242,243,237,.9); }
.search-box { height: 44px; width: min(410px, 38vw); display: flex; align-items: center; gap: 9px; border: 1px solid #b9c0b5; background: white; padding: 0 12px; }
.search-box:focus-within { outline: 3px solid var(--focus); outline-offset: 1px; }
.search-box input { min-width: 0; flex: 1; border: 0; outline: 0; background: transparent; }
.search-box svg { color: var(--slate); }
kbd { border: 1px solid var(--line); background: var(--paper); padding: 1px 6px; color: var(--slate); }
.filter-button, .reset-button, .error-state button, .empty-state button { height: 44px; display: flex; align-items: center; gap: 8px; padding: 0 14px; border: 1px solid #aeb6aa; background: #f7f8f3; font-weight: 680; }
.filter-button.has-filters { border-color: var(--ocean); }
.filter-button b { min-width: 21px; height: 21px; border-radius: 50%; display: grid; place-items: center; background: var(--basalt); color: white; font-size: 11px; }
.reset-button { border: 0; background: transparent; color: #6c5042; }
.sort-control { margin-left: auto; display: flex; align-items: center; gap: 8px; color: var(--slate); font-size: 13px; }
.sort-control select, .filter-panel select { min-height: 42px; border: 1px solid #b8bfb4; background: white; padding: 0 34px 0 11px; }
.filter-panel { padding: 16px 32px 20px; display: grid; grid-template-columns: 1.25fr 1.25fr repeat(4, 1fr); gap: 16px; background: #dde1d8; border-bottom: 1px solid #bdc4b9; box-shadow: inset 0 5px 12px rgba(27,39,35,.05); }
.filter-panel label { min-width: 0; font-size: 12px; font-weight: 720; color: #4b5853; }
.filter-panel output { float: right; color: var(--ink); }
.filter-panel input[type="range"] { width: 100%; margin: 12px 0 0; accent-color: var(--ocean); }
.filter-panel select { display: block; width: 100%; margin-top: 6px; }
.check-control { display: flex; align-items: end; padding-bottom: 2px; }
.check-control input { width: 20px; height: 20px; margin: 0 8px 11px 0; accent-color: var(--ocean); }
.check-control span { min-height: 42px; flex: 1; display: flex; align-items: center; gap: 7px; border: 1px solid #b8bfb4; background: white; padding: 0 10px; }
.mobile-view-tabs { display: none; }

.workspace { display: grid; grid-template-columns: minmax(0, 1.65fr) minmax(345px, .72fr); height: min(630px, calc(100vh - 310px)); min-height: 470px; border-bottom: 1px solid var(--line); position: relative; }
.map-panel { position: relative; min-width: 0; overflow: hidden; border-right: 1px solid var(--line); }
.map-wrap, .map-canvas { width: 100%; height: 100%; background: #dfe4de; }
.leaflet-container { font-family: inherit; }
.leaflet-control-attribution { font-size: 9px !important; background: rgba(244,245,240,.78) !important; }
.leaflet-tooltip { border: 1px solid var(--basalt); border-radius: 0; box-shadow: 4px 4px 0 rgba(24,33,31,.15); padding: 8px 10px; font-size: 12px; }
.quake-marker { stroke: #f3f4ee; }
.marker-minor { fill: var(--minor); }
.marker-moderate { fill: var(--moderate); }
.marker-strong { fill: var(--strong); }
.marker-major { fill: var(--major); }
.marker-unknown { fill: #777; stroke-dasharray: 2 2; }
.quake-marker.is-active { stroke: var(--basalt); filter: drop-shadow(0 0 3px white); }
.map-legend { position: absolute; left: 16px; bottom: 22px; z-index: 500; max-width: 250px; display: flex; flex-wrap: wrap; gap: 7px 12px; background: rgba(246,247,241,.93); border: 1px solid #aeb7ac; padding: 10px 12px; font-size: 11px; box-shadow: 3px 3px 0 rgba(36,49,44,.1); }
.map-legend span { display: flex; align-items: center; gap: 5px; }
.map-legend small { flex-basis: 100%; color: var(--slate); }
.legend-dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; border: 1px solid white; box-shadow: 0 0 0 1px #53625c; }
.legend-dot.minor { background: var(--minor); } .legend-dot.moderate { background: var(--moderate); } .legend-dot.strong { background: var(--strong); } .legend-dot.major { background: var(--major); }
.map-count { position: absolute; right: 14px; top: 14px; z-index: 500; display: flex; align-items: center; gap: 6px; background: var(--basalt); color: white; padding: 7px 10px; font-size: 11px; text-transform: uppercase; letter-spacing: .07em; }
.data-banner { position: absolute; z-index: 600; top: 10px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 7px; background: #fff3db; border: 1px solid #c99041; padding: 8px 12px; font-size: 12px; box-shadow: 2px 2px 0 rgba(60,45,23,.12); }
.data-banner button { border: 0; background: transparent; text-decoration: underline; font-weight: 700; }

.stream-panel { min-width: 0; display: flex; flex-direction: column; background: var(--paper); }
.stream-head { min-height: 67px; padding: 13px 17px 10px; border-bottom: 1px solid var(--line); display: flex; align-items: center; justify-content: space-between; }
.stream-head h2 { margin: 0; font-family: 'Geologica Variable'; font-size: 18px; font-weight: 560; }
.stream-head .section-kicker { margin-bottom: 2px; }
.stream-head > svg { color: var(--slate); }
.stream-body { min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
.event-row { width: 100%; min-height: 86px; display: grid; grid-template-columns: 60px minmax(0, 1fr) auto; gap: 11px; align-items: center; border: 0; border-bottom: 1px solid #d5d9d0; background: transparent; text-align: left; padding: 10px 14px 10px 12px; position: relative; }
.event-row:hover, .event-row.hovered { background: #e8ebe3; }
.event-row.selected { background: #dce4df; box-shadow: inset 4px 0 var(--ocean); }
.event-row.selected::after { content: 'SELECTED'; position: absolute; right: 11px; top: 7px; font-size: 8px; font-weight: 800; letter-spacing: .13em; color: var(--ocean); }
.mag { width: 54px; height: 54px; display: grid; place-items: center; border-radius: 50%; color: white; font-family: 'Geologica Variable'; font-weight: 680; font-size: 14px; border: 3px double rgba(255,255,255,.76); }
.medallion-minor { background: var(--minor); } .medallion-moderate { background: var(--moderate); } .medallion-strong { background: var(--strong); } .medallion-major { background: var(--major); } .medallion-unknown { background: #777; }
.event-copy { min-width: 0; }
.event-copy strong { display: block; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-size: 14px; }
.event-copy > span { margin-top: 6px; display: flex; align-items: center; gap: 5px; color: var(--slate); font-size: 11px; }
.event-signals { max-width: 82px; display: flex; justify-content: end; align-items: end; flex-direction: column; gap: 4px; color: #728079; }
.signal { display: flex; align-items: center; gap: 3px; font-size: 9px; font-weight: 780; text-transform: uppercase; }
.tsunami { color: #315f6a; }
.alert-green { color: #3e7454; } .alert-yellow { color: #765b12; } .alert-orange { color: #a34c20; } .alert-red { color: #9e2e28; }

.detail-panel { position: absolute; z-index: 700; right: 0; top: 0; width: min(430px, 42vw); height: 100%; overflow-y: auto; background: #f5f5ef; border-left: 1px solid var(--basalt); box-shadow: -12px 0 35px rgba(30,39,36,.2); padding: 22px; animation: slide-in .22s ease-out; }
.detail-top { display: flex; justify-content: space-between; align-items: start; }
.detail-panel .icon-button { border-color: var(--line); }
.detail-magnitude { font-family: 'Geologica Variable'; font-size: 57px; font-weight: 730; line-height: 1; letter-spacing: -.07em; color: var(--rust); }
.assessment { display: inline-flex; align-items: center; gap: 7px; margin: 13px 0 18px; padding: 7px 9px; border: 1px solid currentColor; font-size: 11px; font-weight: 760; text-transform: uppercase; letter-spacing: .05em; }
.assessment-minor, .assessment-moderate { color: var(--ocean); } .assessment-strong { color: #9a571f; } .assessment-major { color: var(--rust); }
.detail-panel h2 { margin-bottom: 8px; font-family: 'Geologica Variable'; font-size: 25px; font-weight: 550; line-height: 1.16; letter-spacing: -.025em; }
.detail-time { color: var(--ink); display: grid; grid-template-columns: 18px 1fr; column-gap: 7px; align-items: center; font-weight: 670; }
.detail-time span { grid-column: 2; color: var(--slate); font-size: 12px; font-weight: 450; }
.detail-grid { display: grid; grid-template-columns: 1fr 1fr; border-top: 1px solid var(--line); border-left: 1px solid var(--line); margin: 21px 0; }
.detail-grid > div { min-height: 105px; padding: 12px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.detail-grid span { display: flex; align-items: center; gap: 4px; color: var(--slate); font-size: 11px; text-transform: uppercase; letter-spacing: .07em; }
.detail-grid strong { display: block; font-family: 'Geologica Variable'; font-size: 19px; margin: 8px 0 4px; }
.detail-grid small { color: var(--slate); line-height: 1.2; }
.coordinates { display: flex; gap: 7px; align-items: center; font-family: 'Geologica Variable'; padding: 10px 0; border-bottom: 1px solid var(--line); }
.detail-flags { display: flex; flex-wrap: wrap; gap: 8px; padding: 13px 0; }
.detail-flags span { display: flex; gap: 5px; align-items: center; border: 1px solid var(--line); padding: 5px 8px; font-size: 11px; text-transform: capitalize; }
.magnitude-note { background: #e4e7df; border-left: 3px solid var(--mineral); padding: 11px 13px; margin: 9px 0 16px; }
.magnitude-note p, .authority-note { margin: 4px 0 0; color: var(--slate); font-size: 12px; line-height: 1.4; }
.usgs-link { min-height: 46px; display: flex; justify-content: center; align-items: center; gap: 8px; background: var(--basalt); color: white; text-decoration: none; font-weight: 700; }
.authority-note { margin-top: 12px; }

.timeline { background: var(--basalt); color: #edf0e9; padding: 16px 31px 19px; border-bottom: 1px solid #3b4641; }
.timeline-heading { display: flex; justify-content: space-between; align-items: end; }
.timeline-heading .section-kicker { color: #91a098; }
.timeline-heading h2 { margin: 0; font-family: 'Geologica Variable'; font-size: 17px; font-weight: 480; }
.timeline-heading p { margin: 0; color: #aeb8b2; font-size: 12px; max-width: 40%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.trace { position: relative; height: 90px; margin: 5px 0 0; }
.trace svg { display: block; width: 100%; height: 79px; overflow: visible; }
.trace-baseline { stroke: #53625c; stroke-width: .25; vector-effect: non-scaling-stroke; }
.trace-line { fill: none; stroke: #889890; stroke-width: .42; vector-effect: non-scaling-stroke; opacity: .65; }
.trace-point { fill: #d4a25c; stroke: var(--basalt); stroke-width: .28; vector-effect: non-scaling-stroke; }
.trace-point.selected { fill: #f7e7c8; stroke: #d16b42; stroke-width: .8; }
.timeline-start, .timeline-end { position: absolute; bottom: 0; color: #7f8d86; font-size: 10px; text-transform: uppercase; letter-spacing: .1em; }
.timeline-start { left: 0; } .timeline-end { right: 0; }
.scrubber-label { display: block; position: relative; height: 16px; margin-top: -33px; margin-bottom: 17px; }
.scrubber { appearance: none; width: 100%; height: 16px; opacity: .01; cursor: ew-resize; }
.scrubber:focus-visible { opacity: .3; outline-color: #e7be7d; }
.timeline-accessible { margin: 4px 0 0; color: #91a098; font-size: 11px; }

.loading-shell { height: 520px; display: grid; grid-template-columns: 2fr 1fr; gap: 1px; background: var(--line); }
.skeleton { background: linear-gradient(100deg, #dde1d8 30%, #eef0e9 50%, #dde1d8 70%); background-size: 200% 100%; animation: shimmer 1.5s infinite; }
.skeleton-lines { padding: 20px; background: var(--paper); }
.skeleton-lines .skeleton { height: 64px; margin-bottom: 10px; }
.error-state, .empty-state { min-height: 320px; display: grid; place-items: center; align-content: center; text-align: center; padding: 30px; }
.error-state > svg, .empty-state > svg { width: 36px; height: 36px; color: var(--rust); margin-bottom: 12px; }
.error-state h2, .empty-state h3 { margin-bottom: 7px; font-family: 'Geologica Variable'; }
.error-state p, .empty-state p { max-width: 460px; color: var(--slate); }
.error-state button, .empty-state button { margin: auto; }

footer { min-height: 62px; padding: 13px 31px; background: var(--basalt); color: #9eaaa4; display: flex; justify-content: space-between; align-items: center; gap: 20px; font-size: 11px; }
footer div { display: flex; align-items: center; gap: 6px; }
footer a { color: #dce1dd; }

@keyframes spin { to { transform: rotate(360deg); } }
@keyframes shimmer { to { background-position: -200% 0; } }
@keyframes slide-in { from { transform: translateX(40px); opacity: .2; } }

@media (max-width: 1050px) {
  .topbar { grid-template-columns: 230px 1fr auto; padding: 0 18px; }
  .live-status span { display: none; }
  .overview-summary div { min-width: 105px; padding-inline: 12px; }
  .filter-panel { grid-template-columns: repeat(3, 1fr); }
  .workspace { grid-template-columns: 1.45fr minmax(330px, .8fr); }
  .timeline { padding-inline: 20px; }
}

@media (max-width: 760px) {
  .topbar { height: auto; min-height: 64px; padding: 9px 12px; grid-template-columns: 1fr auto; }
  .brand small { display: none; }
  .range-tabs { grid-row: 2; grid-column: 1 / -1; width: 100%; margin-top: 9px; }
  .range-tabs button { flex: 1; padding-inline: 6px; min-height: 40px; }
  .top-actions .live-status, .top-actions button:last-child { display: none; }
  .overview-head { min-height: 0; display: block; padding: 20px 16px 15px; }
  .headline h1 { font-size: 27px; }
  .headline p { font-size: 13px; }
  .overview-summary { margin-top: 18px; width: 100%; }
  .overview-summary div { flex: 1; min-width: 0; padding: 11px 8px; }
  .overview-summary strong { font-size: 18px; }
  .overview-summary span { font-size: 9px; }
  .control-deck { padding: 9px 12px; flex-wrap: wrap; }
  .search-box { width: calc(100% - 112px); flex: 1; }
  kbd, .sort-control > span { display: none; }
  .sort-control { margin-left: 0; flex: 1; }
  .sort-control select { width: 100%; }
  .reset-button { padding-inline: 8px; }
  .filter-panel { padding: 14px 12px; grid-template-columns: 1fr 1fr; gap: 13px 10px; max-height: 52vh; overflow-y: auto; }
  .filter-panel .check-control { grid-column: 1 / -1; }
  .mobile-view-tabs { display: grid; grid-template-columns: 1fr 1fr; padding: 8px 12px; gap: 8px; background: #d8dcd3; border-bottom: 1px solid var(--line); }
  .mobile-view-tabs button { min-height: 44px; border: 1px solid #adb5aa; background: #eceee7; display: flex; align-items: center; justify-content: center; gap: 7px; font-weight: 700; }
  .mobile-view-tabs button.active { background: var(--basalt); color: white; border-color: var(--basalt); }
  .workspace { height: 58vh; min-height: 480px; display: block; }
  .workspace.mobile-map .stream-panel, .workspace.mobile-list .map-panel { display: none; }
  .map-panel, .stream-panel { width: 100%; height: 100%; border: 0; }
  .map-legend { left: 9px; bottom: 17px; max-width: 224px; padding: 8px; gap: 5px 9px; }
  .data-banner { width: calc(100% - 20px); justify-content: center; }
  .event-row { min-height: 82px; grid-template-columns: 55px minmax(0, 1fr) auto; padding-inline: 10px; }
  .mag { width: 50px; height: 50px; }
  .event-copy strong { white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  .detail-panel { position: fixed; width: 100%; height: min(78vh, 680px); top: auto; bottom: 0; border: 0; border-top: 2px solid var(--basalt); box-shadow: 0 -18px 45px rgba(20,29,26,.28); padding: 18px 16px 28px; animation: sheet-in .24s ease-out; }
  .detail-magnitude { font-size: 46px; }
  .detail-panel h2 { font-size: 22px; }
  .timeline { padding: 15px 13px; }
  .timeline-heading p { display: none; }
  .trace { height: 78px; }
  .timeline-accessible { line-height: 1.35; }
  footer { display: block; padding: 17px 15px; }
  footer div + div { margin-top: 9px; }
  .loading-shell { height: 500px; grid-template-columns: 1fr; }
  .skeleton-lines { display: none; }
}

@keyframes sheet-in { from { transform: translateY(50px); opacity: .3; } }

@media (max-width: 410px) {
  .brand strong { font-size: 18px; }
  .topbar .icon-button { width: 42px; height: 42px; }
  .headline h1 { font-size: 24px; }
  .overview-summary div:last-child { display: none; }
  .filter-panel { grid-template-columns: 1fr; }
  .filter-panel .check-control { grid-column: auto; }
  .filter-button { padding-inline: 11px; }
  .sort-control { min-width: 180px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

@media (forced-colors: active) {
  .quake-marker, .legend-dot, .mag { forced-color-adjust: none; border: 2px solid CanvasText; }
  .event-row.selected { outline: 3px solid Highlight; }
}

